// Generated from the editable example files. Run npm run examples:sync after changing them.
export const patientRecordsHtml = "@if (detail()) {\n  <good-main-view>\n    <good-avatar goodMainViewLeading [name]=\"store.patient().name\" size=\"large\" [decorative]=\"true\" />\n    <good-heading-1>{{ store.patient().name }}</good-heading-1>\n    <good-summary>Patient DEMO-001 · Patient record</good-summary>\n    <good-action-group good-main-view-actions ariaLabel=\"Patient record actions\" spacing=\"small\">\n      <good-button variant=\"outline\" [icon]=\"refreshIcon\" [iconOnly]=\"true\" ariaLabel=\"Refresh record\" (click)=\"refresh()\" />\n      <good-button [icon]=\"plusIcon\" (click)=\"startEntry()\">New entry</good-button>\n    </good-action-group>\n    <good-group appearance=\"plain\">\n      <good-link route=\"/examples/patient-records\">← All patients</good-link>\n      <good-card appearance=\"contrast\">\n        <good-card-header title=\"Patient details\">\n          <good-action-group goodCardActions spacing=\"small\"><good-button size=\"small\" variant=\"ghost\" [icon]=\"editIcon\" (click)=\"startEdit()\">Edit details</good-button></good-action-group>\n        </good-card-header>\n        <good-detail-list layout=\"grid\" [columns]=\"3\">\n          <div goodDetailRow><dt>Name</dt><dd>{{ store.patient().name }}</dd></div>\n          <div goodDetailRow><dt>Date of birth</dt><dd>{{ store.patient().birthDate || 'Not provided' }}</dd></div>\n          <div goodDetailRow><dt>Patient number</dt><dd>DEMO-001</dd></div>\n          <div goodDetailRow><dt>Email</dt><dd>{{ store.patient().email || 'Not provided' }}</dd></div>\n          <div goodDetailRow><dt>Landline</dt><dd>{{ store.patient().landline || 'Not provided' }}</dd></div>\n          <div goodDetailRow><dt>Mobile</dt><dd>{{ store.patient().mobile || 'Not provided' }}</dd></div>\n          <div goodDetailRow><dt>Address</dt><dd>{{ store.patient().address || 'Not provided' }}</dd></div>\n        </good-detail-list>\n      </good-card>\n      <good-tabs ariaLabel=\"Patient record sections\" [(activeId)]=\"activeTab\">\n        <good-tab value=\"activity\" label=\"Activity\">\n          <good-card appearance=\"contrast\">\n            <good-card-header [title]=\"'Record entries · ' + filteredEntries().length\">\n              <span goodCardSubtitle>Treatments and notes at a glance</span>\n              <good-action-group goodCardActions spacing=\"small\"><good-select label=\"Filter entry type\" size=\"small\" [options]=\"filterOptions\" [value]=\"filter()\" (valueChange)=\"filter.set($event)\" /></good-action-group>\n            </good-card-header>\n            <good-table label=\"Record entries\" [data]=\"filteredEntries()\" [columns]=\"entryColumns\" [getRowId]=\"rowId\" [reorderable]=\"false\" frameAppearance=\"none\" [pagination]=\"store.entries().length ? { mode: 'client', pageSize: 10 } : null\">\n              <ng-template goodTableEmpty>\n                @if (store.entries().length) {\n                  <good-empty-state title=\"No matching entries\" description=\"Choose another entry type to see the rest of this record.\"><good-button variant=\"outline\" (click)=\"filter.set('all')\">Clear filter</good-button></good-empty-state>\n                } @else {\n                  <good-empty-state title=\"No record entries yet\" description=\"Document the first treatment or add a note to this patient record.\"><good-button [icon]=\"plusIcon\" (click)=\"startEntry()\">Create first entry</good-button></good-empty-state>\n                }\n              </ng-template>\n            </good-table>\n          </good-card>\n        </good-tab>\n        <good-tab value=\"documents\" label=\"Documents\" [badge]=\"store.documents().length\">\n          <good-card appearance=\"contrast\">\n            <good-card-header title=\"Documents\"><span goodCardSubtitle>Files stay in this browser session and are never uploaded.</span></good-card-header>\n            <good-input label=\"Attach documents\" [showLabel]=\"true\" type=\"file\" [multiple]=\"true\" (filesChange)=\"addDocuments($event)\" />\n            <good-table label=\"Patient documents\" [data]=\"store.documents()\" [columns]=\"documentColumns\" [getRowId]=\"rowId\" frameAppearance=\"none\" [reorderable]=\"false\">\n              <ng-template goodTableCell=\"actions\" let-document><good-action-group spacing=\"small\"><good-button variant=\"ghost\" size=\"small\" [icon]=\"downloadIcon\" (click)=\"download(document)\">Download</good-button><good-button variant=\"ghost\" size=\"small\" (click)=\"removeDocument(document.id)\">Remove</good-button></good-action-group></ng-template>\n              <ng-template goodTableEmpty><good-empty-state [icon]=\"fileIcon\" title=\"No documents attached\" description=\"Choose a file above to add it to this demo record.\" /></ng-template>\n            </good-table>\n          </good-card>\n        </good-tab>\n        <good-tab value=\"details\" label=\"Details\">\n          <good-card appearance=\"contrast\"><good-card-header title=\"Contact details\"><good-action-group goodCardActions><good-button variant=\"ghost\" size=\"small\" [icon]=\"editIcon\" (click)=\"startEdit()\">Edit patient details</good-button></good-action-group></good-card-header><good-detail-list layout=\"grid\"><div goodDetailRow><dt>Landline</dt><dd>{{ store.patient().landline || 'Not provided' }}</dd></div><div goodDetailRow><dt>Mobile</dt><dd>{{ store.patient().mobile || 'Not provided' }}</dd></div><div goodDetailRow><dt>Email</dt><dd>{{ store.patient().email || 'Not provided' }}</dd></div><div goodDetailRow><dt>Postal address</dt><dd>{{ store.patient().address || 'Not provided' }}</dd></div></good-detail-list></good-card>\n        </good-tab>\n      </good-tabs>\n      <good-paragraph role=\"status\">{{ updated() }}</good-paragraph>\n      <good-action-group spacing=\"small\"><good-button variant=\"ghost\" size=\"small\" (click)=\"sourceOpen.set(true)\">View example source</good-button></good-action-group>\n    </good-group>\n  </good-main-view>\n} @else {\n  <good-main-view>\n    <good-heading-1>Patients</good-heading-1><good-summary>Open a patient to read their details and activity.</good-summary>\n    <good-group appearance=\"plain\">\n      <good-table title=\"Patient directory\" label=\"Patient directory\" [data]=\"patientRows()\" [columns]=\"patientColumns\" [searchTerm]=\"query()\" [reorderable]=\"false\">\n        <good-input goodTableActions label=\"Search patients\" placeholder=\"Search patients\" type=\"search\" size=\"small\" [value]=\"query()\" (valueChange)=\"query.set($event)\" />\n        <ng-template goodTableCell=\"name\" let-patient><good-link route=\"/examples/patient-records/example\">{{ patient.name }}</good-link></ng-template>\n      </good-table>\n      <good-paragraph>This example uses fictional data held in memory. Reloading restores the initial record.</good-paragraph>\n      <good-button variant=\"ghost\" size=\"small\" (click)=\"sourceOpen.set(true)\">View example source</good-button>\n    </good-group>\n  </good-main-view>\n}\n<good-modal [(open)]=\"editing\" size=\"large\" [scrollBody]=\"true\">\n  <good-modal-header title=\"Edit patient details\" description=\"Cancel discards your changes.\" />\n  <form goodForm [fullWidth]=\"true\" [formGroup]=\"patientForm\" (ngSubmit)=\"savePatient()\">\n    <good-form-row><good-input label=\"Name\" [showLabel]=\"true\" [required]=\"true\" formControlName=\"name\" /><good-date-input label=\"Date of birth\" [showLabel]=\"true\" locale=\"en-US\" formControlName=\"birthDate\" /></good-form-row>\n    <good-input label=\"Email\" [showLabel]=\"true\" type=\"email\" formControlName=\"email\" />\n    <good-form-row><good-input-phone label=\"Landline\" [showLabel]=\"true\" locale=\"en-US\" formControlName=\"landline\" /><good-input-phone label=\"Mobile\" [showLabel]=\"true\" locale=\"en-US\" formControlName=\"mobile\" /></good-form-row>\n    <good-input label=\"Address\" [showLabel]=\"true\" formControlName=\"address\" />\n    <good-action-group><good-button type=\"submit\" [disabled]=\"patientForm.invalid\">Save details</good-button><good-button variant=\"outline\" (click)=\"editing.set(false)\">Cancel</good-button></good-action-group>\n  </form>\n</good-modal>\n<good-modal [(open)]=\"creating\">\n  <good-modal-header title=\"New record entry\" />\n  <form goodForm [formGroup]=\"entryForm\" (ngSubmit)=\"saveEntry()\">\n    <good-select label=\"Entry type\" [showLabel]=\"true\" [options]=\"entryTypes\" formControlName=\"kind\" />\n    <good-textarea label=\"Entry text\" [showLabel]=\"true\" [required]=\"true\" formControlName=\"summary\" />\n    <good-action-group><good-button type=\"submit\" [disabled]=\"entryForm.invalid\">Save entry</good-button><good-button variant=\"outline\" (click)=\"creating.set(false)\">Cancel</good-button></good-action-group>\n  </form>\n</good-modal>\n<good-modal [(open)]=\"sourceOpen\" size=\"large\" [scrollBody]=\"true\">\n  <good-modal-header title=\"Patient record example source\" />\n  <good-code-block [code]=\"htmlSource\" language=\"html\" title=\"patient-records-page.html\" />\n  <good-code-block [code]=\"typescriptSource\" language=\"typescript\" title=\"patient-records-page.ts\" />\n</good-modal>\n";
export const patientRecordsTs = "import { ChangeDetectionStrategy, Component, Injectable, computed, inject, signal } from '@angular/core';\nimport { toSignal } from '@angular/core/rxjs-interop';\nimport { ActivatedRoute } from '@angular/router';\nimport { FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';\nimport {\n  GoodActionGroupComponent, GoodAvatarComponent, GoodDateInputComponent, GoodButtonComponent,\n  GoodCardActionsDirective, GoodCardComponent, GoodCardHeaderComponent, GoodCodeBlockComponent,\n  GoodDetailListComponent, GoodDetailRowDirective, GoodEmptyStateComponent, GoodFormDirective,\n  GoodFormRowComponent, GoodGroupComponent, GoodHeading1Component,\n  GoodInputComponent, GoodInputPhoneComponent, GoodLinkComponent, GoodMainViewComponent,\n  GoodModalComponent, GoodModalHeaderComponent, GoodParagraphComponent, GoodSelectComponent,\n  GoodSummaryComponent, GoodTabComponent, GoodTableCellDirective, GoodTableComponent,\n  GoodTableEmptyDirective, GoodTabsComponent, GoodTextareaComponent,\n  LucideDownload, LucideFileText, LucidePencil, LucidePlus, LucideRefreshCw,\n  type GoodTableColumn,\n} from '@cloudfrogger/goodui';\nimport { patientRecordsHtml, patientRecordsTs } from './source-code.generated';\n\ninterface Patient { name: string; birthDate: string; email: string; landline: string; mobile: string; address: string }\ninterface RecordEntry { id: number; date: string; kind: string; summary: string; author: string }\ninterface DocumentEntry { id: number; name: string; file: File }\n@Injectable({ providedIn: 'root' })\nexport class PatientRecordsDemoStore {\n  readonly patient = signal<Patient>({ name: 'Example Patient', birthDate: '1990-01-15', email: 'patient@example.test', landline: '+12025550124', mobile: '+12025550125', address: 'Sample address, Example City' });\n  readonly entries = signal<RecordEntry[]>([]);\n  readonly documents = signal<DocumentEntry[]>([]);\n  private nextId = 0;\n  next(): number { return ++this.nextId; }\n}\n\n@Component({\n  selector: 'example-patient-records-page', standalone: true, changeDetection: ChangeDetectionStrategy.OnPush,\n  imports: [ReactiveFormsModule, GoodActionGroupComponent, GoodAvatarComponent, GoodDateInputComponent,\n    GoodButtonComponent, GoodCardActionsDirective, GoodCardComponent, GoodCardHeaderComponent,\n    GoodCodeBlockComponent, GoodDetailListComponent, GoodDetailRowDirective, GoodEmptyStateComponent,\n    GoodFormDirective, GoodFormRowComponent, GoodGroupComponent, GoodHeading1Component,\n    GoodInputComponent, GoodInputPhoneComponent, GoodLinkComponent, GoodMainViewComponent,\n    GoodModalComponent, GoodModalHeaderComponent, GoodParagraphComponent, GoodSelectComponent,\n    GoodSummaryComponent, GoodTabComponent, GoodTableCellDirective, GoodTableComponent,\n    GoodTableEmptyDirective, GoodTabsComponent, GoodTextareaComponent],\n  templateUrl: './patient-records-page.html',\n})\nexport class PatientRecordsPageComponent {\n  readonly store = inject(PatientRecordsDemoStore);\n  private readonly params = toSignal(inject(ActivatedRoute).paramMap);\n  readonly detail = computed(() => !!this.params()?.get('id'));\n  readonly activeTab = signal<string | null>('activity');\n  readonly filter = signal<string | readonly string[] | null>('all');\n  readonly filteredEntries = computed(() => this.store.entries().filter(entry => this.filter() === 'all' || entry.kind === this.filter()));\n  readonly patientRows = computed(() => [{ ...this.store.patient(), id: 'example', number: 'DEMO-001' }]);\n  readonly query = signal('');\n  readonly editing = signal(false);\n  readonly creating = signal(false);\n  readonly sourceOpen = signal(false);\n  readonly updated = signal('Sample data loaded');\n  readonly plusIcon = LucidePlus;\n  readonly editIcon = LucidePencil;\n  readonly refreshIcon = LucideRefreshCw;\n  readonly fileIcon = LucideFileText;\n  readonly downloadIcon = LucideDownload;\n  readonly filterOptions = [{ value: 'all', label: 'All entry types' }, { value: 'Note', label: 'Notes' }, { value: 'Treatment', label: 'Treatments' }];\n  readonly entryTypes = this.filterOptions.slice(1);\n  readonly patientForm = new FormGroup({\n    name: new FormControl('', { nonNullable: true, validators: [Validators.required, Validators.pattern(/\\S/)] }),\n    birthDate: new FormControl('', { nonNullable: true }),\n    email: new FormControl('', { nonNullable: true, validators: [Validators.email] }),\n    landline: new FormControl('', { nonNullable: true }), mobile: new FormControl('', { nonNullable: true }),\n    address: new FormControl('', { nonNullable: true }),\n  });\n  readonly entryForm = new FormGroup({\n    kind: new FormControl('Note', { nonNullable: true, validators: [Validators.required] }),\n    summary: new FormControl('', { nonNullable: true, validators: [Validators.required, Validators.pattern(/\\S/)] }),\n  });\n  readonly patientColumns: GoodTableColumn<Patient & { id: string; number: string }>[] = [\n    { accessorKey: 'name', header: 'Name' }, { accessorKey: 'number', header: 'Patient number' },\n  ];\n  readonly entryColumns: GoodTableColumn<RecordEntry>[] = [\n    { accessorKey: 'date', header: 'Date', cell: info => new Intl.DateTimeFormat('en-US', { dateStyle: 'medium' }).format(new Date(String(info.getValue()))), enableSorting: false },\n    { accessorKey: 'kind', header: 'Type', enableSorting: false },\n    { accessorKey: 'summary', header: 'Entry', enableSorting: false },\n    { accessorKey: 'author', header: 'Author', enableSorting: false, meta: { visibleFrom: 'md' } },\n  ];\n  readonly documentColumns: GoodTableColumn<DocumentEntry>[] = [\n    { accessorKey: 'name', header: 'Document' }, { id: 'actions', header: 'Actions', cell: () => '', meta: { align: 'end' } },\n  ];\n  readonly rowId = (row: { id: number | string }) => String(row.id);\n  readonly htmlSource = patientRecordsHtml;\n  readonly typescriptSource = patientRecordsTs;\n  startEdit(): void { this.patientForm.reset(this.store.patient()); this.editing.set(true); }\n  savePatient(): void {\n    this.patientForm.markAllAsTouched(); if (this.patientForm.invalid) return;\n    this.store.patient.set(this.patientForm.getRawValue()); this.editing.set(false); this.refresh();\n  }\n  startEntry(): void { this.entryForm.reset({ kind: 'Note', summary: '' }); this.creating.set(true); }\n  saveEntry(): void {\n    this.entryForm.markAllAsTouched(); if (this.entryForm.invalid) return;\n    this.store.entries.update(entries => [{ id: this.store.next(), date: new Date().toISOString(), ...this.entryForm.getRawValue(), author: 'Demo team' }, ...entries]);\n    this.filter.set('all'); this.activeTab.set('activity'); this.creating.set(false); this.refresh();\n  }\n  refresh(): void { this.updated.set('Last updated: ' + new Intl.DateTimeFormat('en-US', { timeStyle: 'medium' }).format(new Date())); }\n  addDocuments(files: FileList | null): void {\n    if (files?.length) this.store.documents.update(documents => [...documents, ...Array.from(files, file => ({ id: this.store.next(), name: file.name, file }))]);\n    this.refresh();\n  }\n  download(document: DocumentEntry): void {\n    const url = URL.createObjectURL(document.file); const link = window.document.createElement('a');\n    link.href = url; link.download = document.name; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000);\n  }\n  removeDocument(id: number): void { this.store.documents.update(documents => documents.filter(document => document.id !== id)); }\n}\n";
